    @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);prefs=getSharedPreferences("data",0);apiKey=prefs.getString("td_api_key","");seedStocks();if(!prefs.getBoolean("setup_complete",false))showSetup();else showHome();}
