    void header(String title,String subtitle){LinearLayout h=row();TextView logo=bold("ANTVANCE\nFINANCE",15);h.addView(logo,new LinearLayout.LayoutParams(0,dp(52),1));TextView s=text("⌕",28,WHITE);s.setGravity(Gravity.CENTER);h.addView(s,new LinearLayout.LayoutParams(dp(42),dp(52)));TextView n=text("●",15,RED);n.setGravity(Gravity.CENTER);h.addView(n,new LinearLayout.LayoutParams(dp(34),dp(52)));content.addView(h);TextView t=bold(title,26);t.setPadding(0,dp(7),0,0);content.addView(t);content.addView(small(subtitle));}
